/**
 * Copies the YAML `@example` of every built-in action out of its JSDoc
 * (src/action/actions/<group>/actions.ts) into src/engine/actionExamples.generated.ts,
 * so the assistant can read them at runtime, where the .ts sources aren't shipped.
 *
 *   npm -w apps/core run generate:examples
 *
 * tests/engine/actionExamples.test.ts fails when the generated file is out of date.
 * The same comments feed the Actions pages of the docs (apps/docs/scripts/generate-actions.ts).
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { getGroupActionsMap } from '@tipeline/schemas';

const HERE = path.dirname(fileURLToPath(import.meta.url));
export const ACTIONS_DIR = path.resolve(HERE, '../src/action/actions');
export const OUTPUT_FILE = path.resolve(HERE, '../src/engine/actionExamples.generated.ts');

// A JSDoc block directly followed by a static method: the block documents that action.
const DOC_THEN_METHOD = /\/\*\*([\s\S]*?)\*\/\s*static\s+(?:async\s+)?(\w+)\s*\(/g;
const EXAMPLE = /@example[\s\S]*?```yaml\n([\s\S]*?)```/;

/**
 * "group.name" → example YAML, for every action whose JSDoc has a YAML @example.
 * Only public actions (the ones with a schema) count; helper methods are skipped.
 */
export function extractActionExamples(actionsDir = ACTIONS_DIR): Record<string, string> {
  const examples: Record<string, string> = {};
  const publicActions = getGroupActionsMap();
  const groups = fs
    .readdirSync(actionsDir)
    .filter((entry) => fs.existsSync(path.join(actionsDir, entry, 'actions.ts')))
    .sort();

  for (const group of groups) {
    const source = fs.readFileSync(path.join(actionsDir, group, 'actions.ts'), 'utf8');
    for (const match of source.matchAll(DOC_THEN_METHOD)) {
      const [, doc, name] = match;
      // Strip the leading " * " of each JSDoc line before looking for the example.
      const text = doc.replace(/^[ \t]*\*[ \t]?/gm, '');
      const example = EXAMPLE.exec(text);
      if (example && publicActions[group]?.includes(name)) {
        examples[`${group}.${name}`] = example[1].trimEnd() + '\n';
      }
    }
  }
  return examples;
}

export function renderGeneratedFile(examples: Record<string, string>): string {
  const sorted = Object.fromEntries(Object.entries(examples).sort(([a], [b]) => a.localeCompare(b)));
  return [
    '// Generated by scripts/extractActionExamples.ts from the actions\' JSDoc @example blocks.',
    '// Do not edit: run `npm -w apps/core run generate:examples` after changing an example.',
    '',
    `export const ACTION_EXAMPLES: Record<string, string> = ${JSON.stringify(sorted, null, 2)};`,
    '',
  ].join('\n');
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  const examples = extractActionExamples();
  fs.writeFileSync(OUTPUT_FILE, renderGeneratedFile(examples), 'utf8');
  console.log(`Wrote ${Object.keys(examples).length} action examples to ${path.relative(process.cwd(), OUTPUT_FILE)}`);
}
